import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();

        TreeMap<Integer, Long> totals = new TreeMap<>();
        Map<Integer, Long> startTimes = new HashMap<>();
        Set<Integer> pending = new HashSet<>();

        long time = 0;
        int gap = 1;
        boolean seenEvent = false;

        for (int i = 0; i < n; i++) {
            String type = fs.next();
            int x = fs.nextInt();

            if (type.charAt(0) == 'T') {
                gap = x;
                continue;
            }

            if (seenEvent) {
                time += gap;
            } else {
                seenEvent = true;
            }
            gap = 1;

            int friend = x;
            totals.putIfAbsent(friend, 0L);

            if (type.charAt(0) == 'R') {
                startTimes.put(friend, time);
                pending.add(friend);
            } else if (pending.remove(friend)) {
                totals.put(friend, totals.get(friend) + time - startTimes.get(friend));
                startTimes.remove(friend);
            }
        }

        StringBuilder out = new StringBuilder();
        for (Map.Entry<Integer, Long> entry : totals.entrySet()) {
            int friend = entry.getKey();
            long total = pending.contains(friend) ? -1 : entry.getValue();
            out.append(friend).append(' ').append(total).append('\n');
        }

        System.out.print(out);
    }
}
